function parse_amount(s,    dot, int_part, dec_part, cents, neg) {
    # remove surrounding quotes, spaces, commas
    gsub(/^[ "]+|[ "]+$/, "", s)
    gsub(/,/, "", s)
    neg = 0
    if (substr(s, 1, 1) == "-") {
        neg = 1
        s = substr(s, 2)
    }
    dot = index(s, ".")
    if (dot == 0) {
        int_part = s
        cents = int_part * 100
    } else {
        int_part = substr(s, 1, dot - 1)
        dec_part = substr(s, dot + 1)
        # Pad dec_part or truncate/round to cents
        # Spec says: "Amounts may have 0-3 decimal digits (e.g. 2000, 300.1, 89.990)"
        # "All amount comparisons and sums are exact to the cent"
        while (length(dec_part) < 2) dec_part = dec_part "0"
        # Take first 2 digits (or if 3 digits like 89.990, the 3rd digit is 0)
        dec_part = substr(dec_part, 1, 2)
        cents = int_part * 100 + dec_part
    }
    if (neg) cents = -cents
    return cents
}

