#!/usr/bin/env bash
# Print a deterministic topological build order for a dependency file.
# Usage: order FILE
set -u

if [ "$#" -ne 1 ]; then
    echo "usage: order FILE" >&2
    exit 2
fi
if [ ! -r "$1" ]; then
    echo "order: cannot read '$1'" >&2
    exit 2
fi

LC_ALL=C awk '
{
    sub(/#.*/, "")              # strip comments
    if ($0 !~ /[^ \t]/) next    # skip blank lines
    sub(/:/, " ")               # colon -> first field separator
    pkg = $1
    if (!(pkg in seen)) { seen[pkg] = 1; pkgs[n++] = pkg }
    for (i = 2; i <= NF; i++) {
        d = $i
        if (!(d in seen)) { seen[d] = 1; pkgs[n++] = d }
        if (!(d SUBSEP pkg in edge)) {
            edge[d SUBSEP pkg] = 1        # d must come before pkg
            if (d != pkg) {
                deps[pkg] = deps[pkg] " " d
                deg[pkg]++
            }
        }
    }
}
END {
    # count and list of packages sorted by byte order
    npk = 0
    for (i = 0; i < n; i++) psort[npk++] = pkgs[i]
    for (i = 1; i < npk; i++) {          # insertion sort
        v = psort[i]; j = i - 1
        while (j >= 0 && psort[j] > v) { psort[j+1] = psort[j]; j-- }
        psort[j+1] = v
    }

    emitted = 0
    nr = 0
    for (i = 0; i < npk; i++)
        if (deg[psort[i]] + 0 == 0) ready[nr++] = psort[i]

    while (nr > 0) {
        p = ready[0]                     # smallest ready (byte order)
        for (i = 1; i < nr; i++) ready[i-1] = ready[i]
        nr--
        if (p in done) continue
        done[p] = 1
        print p
        emitted++
        # packages depending on p lose one pending dep
        for (q in deg)
            if (!(q in done) && (p SUBSEP q) in edge) {
                deg[q]--
                if (deg[q] == 0) {
                    ready[nr++] = q
                    for (i = nr - 1; i > 0 && ready[i-1] > q; i--) {
                        ready[i] = ready[i-1]; ready[i-1] = q
                    }
                }
            }
    }

    if (emitted < npk) {
        out = ""
        for (i = 0; i < npk; i++)
            if (!(psort[i] in done))
                out = out (out == "" ? "" : " ") psort[i]
        printf "cycle: %s\n", out > "/dev/stderr"
        exit 1
    }
    exit 0
}
